<?php

declare(strict_types=1); require_once dirname(__DIR__).'/config.php'; admin_required(); $pdo=db();$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim((string)($_POST['title']??''));$notice=trim((string)($_POST['notice']??''));$closed=isset($_POST['closed'])?'1':'0';$st=$pdo->prepare("INSERT INTO gift_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)");foreach([['title',$title],['notice',$notice],['closed',$closed]] as $r)$st->execute($r);$msg='설정을 저장했습니다.';}
$settings=[];foreach($pdo->query("SELECT setting_key,setting_value FROM gift_settings") as $r)$settings[$r['setting_key']]=$r['setting_value'];
?>
<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>환경설정</title><link rel="stylesheet" href="../assets/style.css"></head><body class="admin-body"><?php include __DIR__.'/_nav.php';?><main class="admin-wrap"><div class="page-head"><div><span class="eyebrow">관리</span><h1>환경설정</h1></div></div><?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><section class="card"><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>회원화면 제목<input name="title" value="<?=e($settings['title']??'')?>" required></label><label>안내문<textarea name="notice" rows="5"><?=e($settings['notice']??'')?></textarea></label><label class="check switch-row"><input type="checkbox" name="closed" value="1" <?=($settings['closed']??'0')==='1'?'checked':''?>><span><b>제출 마감</b><small>체크하면 회원 입력화면에서 제출할 수 없습니다.</small></span></label><button class="btn" type="submit">설정 저장</button></form></section><section class="card danger-zone"><h2>보안 안내</h2><p>계좌번호는 민감한 금융정보이므로 관리자 계정 공유를 피하고, 수집 목적이 끝나면 제출내역과 서버 백업본을 함께 삭제하는 것을 권장합니다.</p></section></main></body></html>
